    // MARK: Support

    static let keys = KeyboardLayout.keys(for: .letters, metrics: KeyboardMetrics(width: 390, height: 216), showsGlobe: false)
    static let touch = TapDecoder.TouchModel.standard

    static func centre(_ letter: Character) -> (x: Double, y: Double) {
        let frame = keys.first { $0.action == .character(String(letter)) }!.frame
        return (frame.midX, frame.midY)
    }

    /// One point per character at its key's centre; none for apostrophes and the positions in `none`.
    static func centreTaps(_ word: String, none: Set<Int> = []) -> [(x: Double, y: Double)?] {
        word.enumerated().map { index, character in character == "'" || none.contains(index) ? nil : centre(character) }
    }

    /// P(word) from a table (optionally one per previous word); words outside it get `unknown`.
    final class FakeModel: WordModel {
        let probs: [String: Double]
        let unknown: Double
        let byPrevious: [String: [String: Double]]
        private(set) var contexts: [[String]] = []

        init(_ probs: [String: Double], unknown: Double = 1e-3, byPrevious: [String: [String: Double]] = [:]) {
            self.probs = probs
            self.unknown = unknown
            self.byPrevious = byPrevious
        }

        func inVocab(_ word: String) -> Bool { probs[word] != nil }

        private(set) var forgotten = 0
        func forgetContext() { forgotten += 1 }

        func logProbs(context: [String], words: [String]) -> [Double] {
            contexts.append(context)
            let table = context.last.flatMap { byPrevious[$0] } ?? probs
            return words.map { log(probs[$0] != nil ? table[$0] ?? unknown : unknown) }
        }
    }

    static func lexicon(_ entries: [(String, Int)]) -> WordLexicon {
        try! WordLexicon(data: AutocorrectTestFiles.lexicon(entries))
    }

    static func make(_ entries: [(String, Int)], _ probs: [String: Double], unknown: Double = 1e-3,
                     byPrevious: [String: [String: Double]] = [:], spelling: SpellingTables? = nil) -> Autocorrector {
        Autocorrector(lexicon: lexicon(entries), model: FakeModel(probs, unknown: unknown, byPrevious: byPrevious), touch: touch,
                      spelling: spelling)
    }

    static func params(_ change: (inout AutocorrectParams) -> Void) -> AutocorrectParams {
        var params = AutocorrectParams.standard
        change(&params)
        return params
    }

    static func correct(_ corrector: Autocorrector, _ context: String, _ word: String, _ points: [(x: Double, y: Double)?]? = nil,
                        _ params: AutocorrectParams = .standard) -> String {
        corrector.correct(context: context, word: word, points: points ?? centreTaps(word), keys: keys, params: params)
    }

    // MARK: Contract

    private static func testSentenceWordsAreTheLastSentencesTokens() {
        TestSupport.expectEqual(Autocorrector.sentenceWords("it's 0 late. i came # "), ["i", "came"])
        TestSupport.expectEqual(Autocorrector.sentenceWords("'tis the 'end' of''it '"), ["tis", "the", "end", "of''it"])
        TestSupport.expectEqual(Autocorrector.sentenceWords("done."), [])
        TestSupport.expectEqual(Autocorrector.sentenceWords(""), [])
        TestSupport.expectEqual(Autocorrector.sentenceWords("a.b. c d0e"), ["c", "d", "e"])
        TestSupport.expectEqual(Autocorrector.sentenceWords("' '' x"), ["x"])
    }

    /// Optimal string alignment distance: Levenshtein plus adjacent transpositions, no substring edited twice.
    static func osa(_ a: [Character], _ b: [Character]) -> Int {
        var d = [[Int]](repeating: [Int](repeating: 0, count: b.count + 1), count: a.count + 1)
        for i in 0 ... a.count { d[i][0] = i }
        for j in 0 ... b.count { d[0][j] = j }
        for i in stride(from: 1, through: a.count, by: 1) {
            for j in stride(from: 1, through: b.count, by: 1) {
                d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] == b[j - 1] ? 0 : 1))
                if i > 1, j > 1, a[i - 1] == b[j - 2], a[i - 2] == b[j - 1] { d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1) }
            }
        }
        return d[a.count][b.count]
    }

    static func limit(_ key: String, _ p: AutocorrectParams) -> Int {
        key.count <= p.shortLength ? p.maxEditsShort : p.maxEdits
    }

    static func randomWord(_ alphabet: [Character], _ lengths: ClosedRange<Int>, _ random: inout SplitMix64) -> String {
        String((0 ..< Int.random(in: lengths, using: &random)).map { _ in alphabet.randomElement(using: &random)! })
    }

    private static func testCandidatesAreTheKeysWithinTheEditLimit() {
        var random = SplitMix64(seed: 1)
        let alphabet = Array("abcd")
        let words = Set((0 ..< 500).map { _ in randomWord(alphabet, 1 ... 7, &random) })
        let lexicon = lexicon(words.map { ($0, 100) })
        let sortedKeys = words.sorted()
        var typed = (0 ..< 40).map { _ in randomWord(alphabet, 1 ... 8, &random) }
        typed += ["abab", "ba", "dcba", "aaaa"]
        let corrector = Autocorrector(lexicon: lexicon, model: FakeModel([:]), touch: touch)
        let cases = [params { _ in }, params { $0.maxEdits = 1; $0.maxEditsShort = 0; $0.shortLength = 2 },
                     params { $0.maxEdits = 2; $0.maxEditsShort = 2; $0.shortLength = 0 },
                     params { $0.maxEdits = 3; $0.maxEditsShort = 1 }]
        for p in cases {
            for t in typed {
                let want = sortedKeys.filter { osa(Array(t), Array($0)) <= limit(t, p) }
                TestSupport.expect(corrector.candidates(key: t, params: p) == want, "candidates \(t) \(p)")
            }
        }
        TestSupport.expectEqual(lexicon.keyCount, words.count)
    }

    private static func testTranspositionCountsAsOneEdit() {
        let corrector = Autocorrector(lexicon: lexicon([("abcd", 1), ("badc", 1), ("bacd", 1)]), model: FakeModel([:]), touch: touch)
        TestSupport.expectEqual(corrector.candidates(key: "abcd", params: params { $0.maxEdits = 1; $0.shortLength = 0 }),
                                ["abcd", "bacd"])
    }

    // MARK: Brute force

    /// The module contract transcribed by brute force: every lexicon key, every alignment, and with `spelling`
    /// the spelling channel's terms. Returns the decision and how close it is to a floating-point tie (cases
    /// closer than 1e-6 are skipped).
    static func referenceCorrect(entries: [String: Int], model: WordModel, p: AutocorrectParams, context: String, typed: String,
                                 taps: [(x: Double, y: Double)?], spelling: SpellingTables? = nil) -> (String, Double) {
        guard let reference = referenceScores(entries: entries, model: model, p: p, context: context, typed: typed, taps: taps,
                                              spelling: spelling)
        else { return (typed, 0) }
        let (keep, scored) = reference
        guard !scored.isEmpty else { return (typed, .infinity) }
        let (score, form) = scored[0]
        var gap = scored.dropFirst().filter { $0.1 != form }.map { score - $0.0 }.min() ?? .infinity
        if form == typed { return (typed, gap) }
        let key = Autocorrector.key(of: typed)
        let margin = entries[typed] == nil ? p.marginOOV : Autocorrector.key(of: form) == key ? p.marginApostrophe : p.marginKnown
        let threshold = margin > 0 ? log(margin) : -.infinity
        gap = min(gap, abs(score - keep - threshold))
        return (score - keep >= threshold ? form : typed, gap)
    }

    /// The contract's keep score and every candidate form's score, ranked (higher score, then higher frequency,
    /// then the first form); nil for a key shorter than `minLength`. Without `spelling` (or at `wSpelling` 0)
    /// the motor channel alone.
    static func referenceScores(entries: [String: Int], model: WordModel, p: AutocorrectParams, context: String, typed: String,
                                taps: [(x: Double, y: Double)?],
                                spelling: SpellingTables? = nil) -> (keep: Double, scored: [(Double, String)])? {
        let key = Autocorrector.key(of: typed)
        guard key.count >= p.minLength else { return nil }
        let letters = Array("abcdefghijklmnopqrstuvwxyz")
        let decoder = TapDecoder(touch: touch, rule: TapDecoder.Rule(centre: 1, margin: 1, maxSurprise: nil))
        let points = zip(typed, taps).filter { $0.0 != "'" }.map(\.1)
        let keyLetters = Array(key)
        var table: [[Character: Double]] = []
        for (i, ch) in keyLetters.enumerated() {
            if let point = points[i] {
                let ll = decoder.logLikelihoods(x: point.x, y: point.y, keys: keys)
                table.append(Dictionary(uniqueKeysWithValues: letters.map { c in
                    (c, ll[keys.firstIndex { $0.action == .character(String(c)) }!])
                }))
            } else {
                table.append(Dictionary(uniqueKeysWithValues: letters.map { ($0, $0 == ch ? 0 : -Double.infinity) }))
            }
        }
        let pad = keys.filter { TapDecoder.outputIndex(of: $0.action) != nil }
        let area = (pad.map { $0.frame.x + $0.frame.width }.max()! - pad.map(\.frame.x).min()!)
            * (pad.map { $0.frame.y + $0.frame.height }.max()! - pad.map(\.frame.y).min()!)
        let lk = log(1 - p.pOmit - p.pInsert - p.pTranspose), lo = log(p.pOmit), lt = log(p.pTranspose)
        // The spelling channel: logaddexp(motor, log wSpelling + spelling) for each edit step.
        let lw = p.wSpelling > 0 ? log(p.wSpelling) : -Double.infinity
        func code(_ c: Character) -> Int { Int(c.asciiValue! - UInt8(ascii: "a")) }
        func either(_ motor: Double, _ spelled: (SpellingTables) -> Double) -> Double {
            guard let spelling, lw > -.infinity else { return motor }
            return TapDecoder.logAddExp(motor, lw + spelled(spelling))
        }
        let pitch = TapDecoder.letterPitch(in: keys)!
        let letterKeys = keys.filter { TapDecoder.outputIndex(of: $0.action).map { $0 < 26 } ?? false }
        func near(_ c: Character) -> [Character] {
            let a = letterKeys.first { $0.action == .character(String(c)) }!
            return letterKeys.filter { b in
                b != a && ((a.frame.midX - b.frame.midX) * (a.frame.midX - b.frame.midX)
                    + (a.frame.midY - b.frame.midY) * (a.frame.midY - b.frame.midY)).squareRoot() <= 1.5 * pitch
            }.map { if case .character(let s) = $0.action { return Character(s) } else { return " " } }
        }
        func inserted(_ i: Int, _ c: Character) -> Double {
            let neighbours = near(c)
            let slip = neighbours.map { exp(table[i][$0]!) }.reduce(0, +) / Double(neighbours.count)
            let q = p.wRepeat * exp(table[i][c]!) + p.wSlip * slip + (1 - p.wRepeat - p.wSlip) / area
            return log(p.pInsert) + log(q)
        }
        let limit = limit(key, p), n = keyLetters.count
        func channel(_ cand: [Character]) -> Double {
            let m = cand.count
            var memo: [Int: Double] = [:]
            func best(_ i: Int, _ j: Int, _ r: Int) -> Double {
                if i == n, j == m { return 0 }
                let id = (i * 64 + j) * 8 + r
                if let value = memo[id] { return value }
                var out = -Double.infinity
                let prior = j == 0 ? SpellingTables.start : code(cand[j - 1])  // the spelling context of step j
                if i < n, j < m {
                    let c = cand[j], x = keyLetters[i]
                    if c == x {
                        out = max(out, lk + table[i][c]! + best(i + 1, j + 1, r))
                    } else if r >= 1 {
                        let step = either(lk + table[i][c]!) { lk + $0.sub[code(c) * 26 + code(x)] + table[i][x]! }
                        out = max(out, step + best(i + 1, j + 1, r - 1))
                    }
                }
                if r >= 1, j < m {
                    out = max(out, either(lo) { $0.dele[prior * 26 + code(cand[j])] } + best(i, j + 1, r - 1))
                }
                if r >= 1, i < n {
                    let x = keyLetters[i]
                    let step = either(inserted(i, cand[max(j - 1, 0)])) { lk + $0.ins[prior * 26 + code(x)] + table[i][x]! }
                    out = max(out, step + best(i + 1, j, r - 1))
                }
                if r >= 1, i + 1 < n, j + 1 < m, cand[j] != cand[j + 1], keyLetters[i] == cand[j + 1], keyLetters[i + 1] == cand[j] {
                    let a = table[i][cand[j + 1]]!, b = table[i + 1][cand[j]]!
                    let step = either(lt + a + b) { 2 * lk + $0.trans[code(cand[j]) * 26 + code(cand[j + 1])] + (a + b) }
                    out = max(out, step + best(i + 2, j + 2, r - 1))
                }
                memo[id] = out
                return out
            }
            return best(0, 0, limit)
        }
        let words = Autocorrector.sentenceWords(context)
        var keep = zip(keyLetters, table).map { lk + $1[$0]! }.reduce(0, +)
        if entries[typed] != nil {
            keep += p.lmWeight * model.logProbs(context: words, words: [typed])[0]
        } else {
            keep += p.lmWeight * model.logProbs(context: words, words: [Autocorrector.unknown])[0] + p.logOOV
        }
        var scored: [(Double, String)] = []
        var byKey: [String: [String]] = [:]
        for form in entries.keys { byKey[Autocorrector.key(of: form), default: []].append(form) }
        for (cand, forms) in byKey where osa(keyLetters, Array(cand)) <= limit {
            let ch = channel(Array(cand))
            for form in forms { scored.append((ch + p.lmWeight * model.logProbs(context: words, words: [form])[0], form)) }
        }
        scored.sort { a, b in
            if a.0 != b.0 { return a.0 > b.0 }
            if entries[a.1]! != entries[b.1]! { return entries[a.1]! > entries[b.1]! }
            return a.1.utf8.lexicographicallyPrecedes(b.1.utf8)
        }
        return (keep, scored)
    }

    /// A tap aimed at a key's centre with Gaussian noise of `sigma` letter pitches (Box–Muller).
    static func sample(_ letter: Character, sigma: Double, _ random: inout SplitMix64) -> (x: Double, y: Double) {
        let pitch = TapDecoder.letterPitch(in: keys)!
        func normal() -> Double {
            let u = Double.random(in: Double.ulpOfOne ..< 1, using: &random), v = Double.random(in: 0 ..< 1, using: &random)
            return (-2 * log(u)).squareRoot() * cos(2 * .pi * v)
        }
        let c = centre(letter)
        return (c.x + normal() * sigma * pitch, c.y + touch.offsetY * pitch + normal() * sigma * pitch)
    }

    private static func testMatchesABruteForceTranscriptionOfTheContract() {
        var random = SplitMix64(seed: 2)
        let alphabet = Array("aqwsde")
        let keySet = Set((0 ..< 160).map { _ in randomWord(alphabet, 1 ... 6, &random) })
        var entries: [String: Int] = [:]
        for k in keySet.sorted() {
            entries[k] = Int.random(in: 0 ... 255, using: &random)
            if k.count > 1, Double.random(in: 0 ..< 1, using: &random) < 0.2 {
                let cut = Int.random(in: 1 ..< k.count, using: &random)
                entries[String(k.prefix(cut)) + "'" + String(k.dropFirst(cut))] = Int.random(in: 0 ... 255, using: &random)
            }
        }
        let lexicon = lexicon(entries.map { ($0.key, $0.value) })
        let forms = entries.keys.sorted()
        var probs: [String: Double] = [:]
        for form in forms { probs[form] = Double.random(in: 1e-4 ... 0.3, using: &random) }
        let model = FakeModel(probs, unknown: 0.02)
        let corrector = Autocorrector(lexicon: lexicon, model: model, touch: touch)
        var decided = 0, changed = 0
        for index in 0 ..< 300 {
            let p = params {
                $0.maxEdits = [1, 2].randomElement(using: &random)!
                $0.maxEditsShort = [0, 1].randomElement(using: &random)!
                $0.shortLength = [2, 3, 4].randomElement(using: &random)!
                $0.minLength = [1, 2].randomElement(using: &random)!
                $0.lmWeight = [0.5, 1, 2].randomElement(using: &random)!
                $0.marginOOV = [1, 3].randomElement(using: &random)!
                $0.marginKnown = [.infinity, 1, 5].randomElement(using: &random)!
                $0.marginApostrophe = [.infinity, 1, 2].randomElement(using: &random)!
                $0.wRepeat = [0.5, 0.2, 0].randomElement(using: &random)!
                $0.wSlip = [0.3, 0.1, 0].randomElement(using: &random)!
            }
            let word = Double.random(in: 0 ..< 1, using: &random) < 0.8 ? forms.randomElement(using: &random)!
                : randomWord(alphabet, 1 ... 6, &random)
            var letters = Array(word)
            for _ in 0 ..< Int.random(in: 0 ... 2, using: &random) {
                let op = Int.random(in: 0 ..< 5, using: &random), at = Int.random(in: 0 ..< letters.count, using: &random)
                switch op {
                case 0 where letters.count > 1 && letters[at] != "'": letters.remove(at: at)
                case 1: letters.insert(alphabet.randomElement(using: &random)!, at: at)
                case 2 where letters[at] != "'": letters[at] = alphabet.randomElement(using: &random)!
                case 3 where at + 1 < letters.count: letters.swapAt(at, at + 1)
                case 4 where letters[at] != "'": letters.insert(letters[at], at: at)
                default: break
                }
            }
            var typed = String(letters).replacingOccurrences(of: "''", with: "'")
            while typed.hasPrefix("'") { typed.removeFirst() }
            while typed.hasSuffix("'") { typed.removeLast() }
            guard !Autocorrector.key(of: typed).isEmpty else { continue }
            let taps: [(x: Double, y: Double)?] = typed.map { ch in
                guard ch != "'", Double.random(in: 0 ..< 1, using: &random) > 0.1 else { return nil }
                let aim = Double.random(in: 0 ..< 1, using: &random) > 0.2 ? ch : alphabet.randomElement(using: &random)!
                return sample(aim, sigma: 0.3, &random)
            }
            let context = ["", "so. ", "we said "].randomElement(using: &random)!
            let (want, gap) = referenceCorrect(entries: entries, model: model, p: p, context: context, typed: typed, taps: taps)
            if gap < 1e-6 { continue }
            decided += 1
            if want != typed { changed += 1 }
            let got = corrector.correct(context: context, word: typed, points: taps, keys: keys, params: p)
            TestSupport.expect(got == want, "case \(index) \(typed): \(got) vs \(want) \(p)")
        }
        TestSupport.expect(decided > 250, "decided \(decided)")
        TestSupport.expect(changed > 50, "changed \(changed)")
    }

    /// A random lexicon over `alphabet` (some forms with apostrophes), as the motor brute force builds it.
    static func referenceEntries(_ alphabet: [Character], _ random: inout SplitMix64) -> [String: Int] {
        var entries: [String: Int] = [:]
        for k in Set((0 ..< 160).map { _ in randomWord(alphabet, 1 ... 6, &random) }).sorted() {
            entries[k] = Int.random(in: 0 ... 255, using: &random)
            if k.count > 1, Double.random(in: 0 ..< 1, using: &random) < 0.2 {
                let cut = Int.random(in: 1 ..< k.count, using: &random)
                entries[String(k.prefix(cut)) + "'" + String(k.dropFirst(cut))] = Int.random(in: 0 ... 255, using: &random)
            }
        }
        return entries
    }

    /// A form (or random letters) with 0-2 random edits, its taps (some missing, some aimed at another letter)
    /// and a context; nil when the edits left no letter.
    static func referenceTyping(_ forms: [String], _ alphabet: [Character],
                                _ random: inout SplitMix64) -> (typed: String, taps: [(x: Double, y: Double)?], context: String)? {
        let word = Double.random(in: 0 ..< 1, using: &random) < 0.8 ? forms.randomElement(using: &random)! : randomWord(alphabet, 1 ... 6, &random)
        var letters = Array(word)
        for _ in 0 ..< Int.random(in: 0 ... 2, using: &random) {
            let op = Int.random(in: 0 ..< 5, using: &random), at = Int.random(in: 0 ..< letters.count, using: &random)
            switch op {
            case 0 where letters.count > 1 && letters[at] != "'": letters.remove(at: at)
            case 1: letters.insert(alphabet.randomElement(using: &random)!, at: at)
            case 2 where letters[at] != "'": letters[at] = alphabet.randomElement(using: &random)!
            case 3 where at + 1 < letters.count: letters.swapAt(at, at + 1)
            case 4 where letters[at] != "'": letters.insert(letters[at], at: at)
            default: break
            }
        }
        var typed = String(letters).replacingOccurrences(of: "''", with: "'")
        while typed.hasPrefix("'") { typed.removeFirst() }
        while typed.hasSuffix("'") { typed.removeLast() }
        guard !Autocorrector.key(of: typed).isEmpty else { return nil }
        let taps: [(x: Double, y: Double)?] = typed.map { ch in
            guard ch != "'", Double.random(in: 0 ..< 1, using: &random) > 0.1 else { return nil }
            let aim = Double.random(in: 0 ..< 1, using: &random) > 0.2 ? ch : alphabet.randomElement(using: &random)!
            return sample(aim, sigma: 0.3, &random)
        }
        return (typed, taps, ["", "so. ", "we said "].randomElement(using: &random)!)
    }

    /// Random parameters with the spelling channel's weight, and edit probabilities that leave the motor channel
    /// weak or without an edit (0), so the spelling terms decide.
    static func spellingParams(_ random: inout SplitMix64) -> AutocorrectParams {
        params {
            $0.maxEdits = [1, 2].randomElement(using: &random)!
            $0.maxEditsShort = [0, 1].randomElement(using: &random)!
            $0.shortLength = [2, 3, 4].randomElement(using: &random)!
            $0.minLength = [1, 2].randomElement(using: &random)!
            $0.lmWeight = [0.5, 1, 2].randomElement(using: &random)!
            $0.marginOOV = [1, 3].randomElement(using: &random)!
            $0.marginKnown = [.infinity, 1, 5].randomElement(using: &random)!
            $0.marginApostrophe = [.infinity, 1, 2].randomElement(using: &random)!
            $0.wRepeat = [0.5, 0.2, 0].randomElement(using: &random)!
            $0.wSlip = [0.3, 0.1, 0].randomElement(using: &random)!
            $0.wSpelling = [0, 0.05, 1, 30].randomElement(using: &random)!
            $0.pOmit = [0.01, 0.2, 0].randomElement(using: &random)!
            $0.pInsert = [0.01, 0.2].randomElement(using: &random)!
            $0.pTranspose = [0.005, 0.2, 0].randomElement(using: &random)!
        }
    }

    private static func testMatchesTheBruteForceTranscriptionWithTheSpellingChannel() {
        var random = SplitMix64(seed: 4)
        let alphabet = Array("aqwsde")
        let entries = referenceEntries(alphabet, &random)
        let forms = entries.keys.sorted()
        var probs: [String: Double] = [:]
        for form in forms { probs[form] = Double.random(in: 1e-4 ... 0.3, using: &random) }
        let model = FakeModel(probs, unknown: 0.02)
        let tables = [AutocorrectTestFiles.randomSpelling(&random), AutocorrectTestFiles.randomSpelling(&random, low: -2)]
        let correctors = tables.map { Autocorrector(lexicon: lexicon(entries.map { ($0.key, $0.value) }), model: model, touch: touch, spelling: $0) }
        var decided = 0, changed = 0, spelled = 0
        for index in 0 ..< 400 {
            let p = spellingParams(&random)
            let which = Int.random(in: 0 ..< tables.count, using: &random)
            guard let typing = referenceTyping(forms, alphabet, &random) else { continue }
            let (typed, taps, context) = typing
            let (want, gap) = referenceCorrect(entries: entries, model: model, p: p, context: context, typed: typed, taps: taps,
                                               spelling: tables[which])
            if gap < 1e-6 { continue }
            decided += 1
            if want != typed { changed += 1 }
            var motor = p
            motor.wSpelling = 0
            if want != referenceCorrect(entries: entries, model: model, p: motor, context: context, typed: typed, taps: taps).0 { spelled += 1 }
            let got = correctors[which].correct(context: context, word: typed, points: taps, keys: keys, params: p)
            TestSupport.expect(got == want, "case \(index) \(typed): \(got) vs \(want) \(p)")
        }
        TestSupport.expect(decided > 350, "decided \(decided)")
        TestSupport.expect(changed > 120, "changed \(changed)")
        TestSupport.expect(spelled > 30, "the spelling terms decided \(spelled)")
    }

    // MARK: Spelling channel

    private static func testZeroSpellingWeightIgnoresTheTables() {
        // wSpelling 0 is the motor channel exactly: the same corrections and suggestions (in order) as without
        // tables. A corrector without tables ignores any weight (motor-only).
        var random = SplitMix64(seed: 7)
        let alphabet = Array("aqwsde")
        let entries = referenceEntries(alphabet, &random)
        let forms = entries.keys.sorted()
        var probs: [String: Double] = [:]
        for form in forms { probs[form] = Double.random(in: 1e-4 ... 0.3, using: &random) }
        let model = FakeModel(probs, unknown: 0.02)
        let lexicon = lexicon(entries.map { ($0.key, $0.value) })
        let plain = Autocorrector(lexicon: lexicon, model: model, touch: touch)
        let ignoring = Autocorrector(lexicon: lexicon, model: model, touch: touch, spelling: AutocorrectTestFiles.randomSpelling(&random, low: -1))
        TestSupport.expect(plain.spelling == nil && ignoring.spelling != nil, "tables kept")
        var compared = 0
        for index in 0 ..< 200 {
            var p = spellingParams(&random)
            p.wSpelling = 0
            guard let typing = referenceTyping(forms, alphabet, &random) else { continue }
            let (typed, taps, context) = typing
            let want = plain.correct(context: context, word: typed, points: taps, keys: keys, params: p)
            TestSupport.expect(ignoring.correct(context: context, word: typed, points: taps, keys: keys, params: p) == want, "case \(index) \(typed)")
            let suggested = plain.suggestions(context: context, word: typed, points: taps, keys: keys, params: p, limit: 10)
            TestSupport.expect(ignoring.suggestions(context: context, word: typed, points: taps, keys: keys, params: p, limit: 10) == suggested,
                               "suggestions \(index) \(typed)")
            var weighted = p
            weighted.wSpelling = 1
            TestSupport.expect(plain.correct(context: context, word: typed, points: taps, keys: keys, params: weighted) == want,
                               "no tables \(index) \(typed)")
            TestSupport.expect(plain.suggestions(context: context, word: typed, points: taps, keys: keys, params: weighted, limit: 10) == suggested,
                               "no tables, suggestions \(index) \(typed)")
            compared += 1
        }
        TestSupport.expect(compared > 150, "compared \(compared)")
    }

    private static func testSpellingWeightIsValidated() {
        // A negative, NaN or infinite weight keeps the word (the reference raises), with or without tables.
        let tables = AutocorrectTestFiles.flatSpelling(log(1e-6), ["trans": [("e", "i", 0.5)]])
        let corrector = make([("receive", 200)], ["receive": 0.5], spelling: tables)
        let plain = make([("receive", 200)], ["receive": 0.5])
        TestSupport.expectEqual(correct(corrector, "i will ", "receve"), "receive")
        TestSupport.expectEqual(correct(corrector, "i will ", "receve", nil, params { $0.wSpelling = 1 }), "receive")
        for weight in [-0.1, -.infinity, .nan, .infinity] {
            TestSupport.expectEqual(correct(corrector, "i will ", "receve", nil, params { $0.wSpelling = weight }), "receve")
            TestSupport.expectEqual(correct(plain, "i will ", "receve", nil, params { $0.wSpelling = weight }), "receve")
            TestSupport.expectEqual(corrector.suggestions(context: "", word: "receve", points: centreTaps("receve"), keys: keys,
                                                          params: params { $0.wSpelling = weight }, limit: 3), [])
        }
    }

    private static func testCognitiveMisspellingIsCorrectedOnlyByTheSpellingChannel() {
        let entries = [("receive", 200), ("relieve", 150)], probs = ["receive": 0.01, "relieve": 0.001]
        let taps = centreTaps("recieve")
        let favoured = AutocorrectTestFiles.flatSpelling(log(1e-6), ["trans": [("e", "i", 0.5)]])
        let corrector = make(entries, probs, unknown: 0.05, spelling: favoured)
        TestSupport.expectEqual(correct(corrector, "i will ", "recieve", taps), "recieve")
        TestSupport.expectEqual(correct(corrector, "i will ", "recieve", taps, params { $0.wSpelling = 1 }), "receive")
        // The tables decide: "ei" typed as "ie" (trans[e, i]), not the reverse.
        let reverse = make(entries, probs, unknown: 0.05, spelling: AutocorrectTestFiles.flatSpelling(log(1e-6), ["trans": [("i", "e", 0.5)]]))
        TestSupport.expectEqual(correct(reverse, "i will ", "recieve", taps, params { $0.wSpelling = 1 }), "recieve")
        TestSupport.expectEqual(correct(corrector, "i will ", "recieve", taps, params { $0.wSpelling = 1e-3 }), "recieve")
        // Suggestions rank the same scores: with the channel the correction comes first.
        TestSupport.expectEqual(corrector.suggestions(context: "i will ", word: "recieve", points: taps, keys: keys,
                                                      params: params { $0.wSpelling = 1 }, limit: 1), ["receive"])
    }

    private static func testSpellingSubstitutionOmissionAndInsertionUseTheirTables() {
        let spelled = params { $0.wSpelling = 1 }
        // "definately": i typed as a, far from i's key.
        let sub = AutocorrectTestFiles.flatSpelling(log(1e-6), ["sub": [("i", "a", 0.3)]])
        let definitely = make([("definitely", 200)], ["definitely": 0.01], unknown: 0.05, spelling: sub)
        TestSupport.expectEqual(correct(definitely, "", "definately"), "definately")
        TestSupport.expectEqual(correct(definitely, "", "definately", nil, spelled), "definitely")
        let reversed = make([("definitely", 200)], ["definitely": 0.01], unknown: 0.05,
                            spelling: AutocorrectTestFiles.flatSpelling(log(1e-6), ["sub": [("a", "i", 0.3)]]))
        TestSupport.expectEqual(correct(reversed, "", "definately", nil, spelled), "definately")
        // "enviroment": n left out after o.
        for (weight, dele, want) in [(0.0, ("o", "n"), "enviroment"), (1.0, ("o", "n"), "environment"), (1.0, ("r", "n"), "enviroment")] {
            let tables = AutocorrectTestFiles.flatSpelling(log(1e-6), ["dele": [(Character(dele.0), Character(dele.1), 0.3)]])
            let corrector = make([("environment", 200)], ["environment": 0.01], unknown: 0.05, spelling: tables)
            TestSupport.expectEqual(correct(corrector, "", "enviroment", nil, params { $0.wSpelling = weight; $0.pOmit = 1e-4 }), want)
        }
        // The first letter left out has the START context.
        for (row, want) in [(Character("^"), "another"), (Character("n"), "nother")] {
            let tables = AutocorrectTestFiles.flatSpelling(log(1e-6), ["dele": [(row, "a", 0.3)]])
            let corrector = make([("another", 200)], ["another": 0.01], unknown: 0.05, spelling: tables)
            TestSupport.expectEqual(correct(corrector, "", "nother", nil, params { $0.wSpelling = 1; $0.pOmit = 1e-4 }), want)
        }
        // "arguement": e typed extra after u.
        let insertion = AutocorrectTestFiles.flatSpelling(log(1e-6), ["ins": [("u", "e", 0.3)]])
        for (weight, want) in [(0.0, "arguement"), (1.0, "argument")] {
            let corrector = make([("argument", 200)], ["argument": 0.01], unknown: 0.05, spelling: insertion)
            TestSupport.expectEqual(correct(corrector, "", "arguement", nil, params { $0.wSpelling = weight; $0.pInsert = 1e-4 }), want)
        }
    }

    private static func testSpellingInsertionBeforeTheFirstLetterHasTheStartContext() {
