    }

    private static func testUntappedLetterCanBeASpellingSubstitution() {
        // A letter without a tap is never a motor substitution, but can be a spelling one (t = 0 at its letter).
        let taps = centreTaps("definately", none: [5])
        let corrector = make([("definitely", 200)], ["definitely": 0.01], unknown: 0.05,
                             spelling: AutocorrectTestFiles.flatSpelling(log(1e-6), ["sub": [("i", "a", 0.3)]]))
