    private static func testBestCandidateDecidesWhichKnownMarginApplies() {
        let entries = [("form", 150), ("for'm", 100), ("from", 200)]
        let probs = ["form": 1e-4, "for'm": 1e-3, "from": 0.1]
        let byPrevious = ["came": ["from": 0.9, "for'm": 1e-3, "form": 1e-4]]
        let corrector = make(entries, probs, byPrevious: byPrevious)
        let apostrophe = params { $0.marginApostrophe = 1 }
        TestSupport.expectEqual(correct(corrector, "i came ", "form", nil, apostrophe), "form")  // "from" is best
        TestSupport.expectEqual(correct(corrector, "the ", "form", nil, apostrophe), "for'm")
        let known = params { $0.marginKnown = 1; $0.marginApostrophe = 1e6 }
        TestSupport.expectEqual(correct(corrector, "i came ", "form", nil, known), "from")
        TestSupport.expectEqual(correct(corrector, "the ", "form", nil, known), "form")
    }

