    /// Suggestions against the brute-force ranking; with `spelling`, random tables and spelling weights.
    private static func suggestionsMatchABruteForceRanking(seed: UInt64, spelling: Bool) {
        var random = SplitMix64(seed: seed)
        let alphabet = Array("aqwsde")
        var entries: [String: Int] = [:]
        for key in Set((0 ..< 160).map { _ in randomWord(alphabet, 1 ... 6, &random) }).sorted() {
            entries[key] = Int.random(in: 0 ... 255, using: &random)
        }
        let lexicon = lexicon(entries.map { ($0.key, $0.value) })
        var probs: [String: Double] = [:]
        for form in entries.keys.sorted() { probs[form] = Double.random(in: 1e-4 ... 0.3, using: &random) }
        let model = FakeModel(probs, unknown: 0.02)
        let tables = spelling ? AutocorrectTestFiles.randomSpelling(&random, low: -3) : nil
        let corrector = Autocorrector(lexicon: lexicon, model: model, touch: touch, spelling: tables)
        var compared = 0
        for index in 0 ..< 200 {
            var p = params {
                $0.maxEdits = [1, 2].randomElement(using: &random)!
                $0.maxEditsShort = [0, 1].randomElement(using: &random)!
                $0.minLength = [1, 2].randomElement(using: &random)!
                $0.lmWeight = [0.5, 1, 2].randomElement(using: &random)!
                $0.marginOOV = [1, .infinity].randomElement(using: &random)!
            }
            if spelling { p.wSpelling = [0.05, 1, 30].randomElement(using: &random)! }
            let typed = randomWord(alphabet, 1 ... 7, &random)
            let taps: [(x: Double, y: Double)?] = typed.map { ch in
                Double.random(in: 0 ..< 1, using: &random) < 0.1 ? nil : sample(ch, sigma: 0.3, &random)
            }
            let limit = Int.random(in: 1 ... 4, using: &random)
            let got = corrector.suggestions(context: "we ", word: typed, points: taps, keys: keys, params: p, limit: limit)
            guard entries[typed] == nil,
                  let reference = referenceScores(entries: entries, model: model, p: p, context: "we ", typed: typed, taps: taps,
                                                  spelling: tables) else {
                TestSupport.expect(got.isEmpty, "case \(index) \(typed): \(got)")
                continue
            }
            let ranked = reference.scored.filter { $0.0.isFinite }
            // Scores this close may rank either way in floating point.
            let shown = min(limit, ranked.count)
            if shown < ranked.count, ranked[shown - 1].0 - ranked[shown].0 < 1e-6 { continue }
            if zip(ranked.prefix(shown), ranked.prefix(shown).dropFirst()).contains(where: { $0.0 - $1.0 < 1e-6 }) { continue }
            compared += 1
            let want = ranked.prefix(shown).map(\.1)
            TestSupport.expect(got == want, "case \(index) \(typed): \(got) vs \(want) \(p)")
        }
        TestSupport.expect(compared > 100, "compared \(compared)")
    }

    private static func testInsertionWeightsWithinRoundingAreNormalized() {
        // The manifest and the settings accept wRepeat + wSlip up to 1 + 1e-9 (rounding): such weights are
        // scaled to sum to 1 (no uniform share), not rejected; a larger sum still keeps every word.
        let corrector = make([("hello", 200)], ["hello": 0.5], unknown: 0.01)
        let over = params { $0.wRepeat = 0.7; $0.wSlip = 0.300000000001 }
        let sum = over.wRepeat + over.wSlip
        let scaled = params { $0.wRepeat = over.wRepeat / sum; $0.wSlip = over.wSlip / sum }
        for word in ["heello", "herllo", "helo"] {
            TestSupport.expectEqual(correct(corrector, "", word, nil, over), "hello")
            TestSupport.expectEqual(correct(corrector, "", word, nil, over), correct(corrector, "", word, nil, scaled))
        }
        TestSupport.expectEqual(correct(corrector, "", "heello", nil, params { $0.wRepeat = 0.7; $0.wSlip = 0.3 + 1e-6 }), "heello")
    }

    private static func testHugeEditLimitsAreTheirUsefulMaximum() {
        // No alignment uses more edits than typed letters plus candidate letters, so any larger limit is that
        // limit: Int.max neither traps nor changes a result.
        let corrector = make([("hello", 200), ("help", 180), ("the", 250)], ["hello": 0.5, "help": 0.2, "the": 0.3])
        for word in ["helo", "hlelo", "teh", "zz"] {
            let huge = params { $0.maxEdits = .max; $0.maxEditsShort = .max }
            let large = params { $0.maxEdits = 40; $0.maxEditsShort = 40 }
            TestSupport.expectEqual(correct(corrector, "", word, nil, huge), correct(corrector, "", word, nil, large))
            TestSupport.expectEqual(corrector.candidates(key: Autocorrector.key(of: word), params: huge),
                                    corrector.candidates(key: Autocorrector.key(of: word), params: large))
        }
    }

    private static func testCorrectionsAreDeterministic() {
        var random = SplitMix64(seed: 3)
        let entries = [("hello", 200), ("help", 180), ("held", 150), ("the", 250), ("then", 200), ("there", 200)]
        let probs = Dictionary(uniqueKeysWithValues: entries.map { ($0.0, 0.1) })
        let cases = (0 ..< 50).map { _ -> (String, [(x: Double, y: Double)?]) in
            let word = entries.randomElement(using: &random)!.0
            return (word, word.map { sample($0, sigma: 0.4, &random) })
        }
        let a = make(entries, probs), b = make(entries, probs)
        let first = cases.map { correct(a, "", $0.0, $0.1) }
        TestSupport.expectEqual(cases.map { correct(a, "", $0.0, $0.1) }, first)
        TestSupport.expectEqual(cases.map { correct(b, "", $0.0, $0.1) }, first)
    }

