        case "lstm": return try! LSTMWordModel(data: AutocorrectFixtures.data(AutocorrectFixtures.lstmBase64), lexicon: fixtureLexicon)
        default: fatalError("unknown model \(name)")
        }
    }

    static var fixtureKeys: [PlacedKey] {
