                            showsGlobe: false)
    }

    static var fixtureTouch: TapDecoder.TouchModel {
        let t = AutocorrectFixtures.touch
        return TapDecoder.TouchModel(sigma: t.sigma, ratio: t.ratio, offsetY: t.offsetY, tailWeight: t.tailWeight, tailScale: t.tailScale,
                                     spaceSpread: t.spaceSpread)
    }

    static func fixtureParams(_ index: Int) -> AutocorrectParams {
