        return AutocorrectParams(pOmit: f.pOmit, pInsert: f.pInsert, pTranspose: f.pTranspose, maxEdits: f.maxEdits,
                                 maxEditsShort: f.maxEditsShort, shortLength: f.shortLength, minLength: f.minLength, lmWeight: f.lmWeight,
                                 logOOV: f.logOOV, marginOOV: f.marginOOV, marginKnown: f.marginKnown,
                                 marginApostrophe: f.marginApostrophe, wRepeat: f.wRepeat, wSlip: f.wSlip, wSpelling: f.wSpelling)
    }

    private static func testLexiconMatchesTheReference() {
        let lexicon = fixtureLexicon
        TestSupport.expectEqual(lexicon.formCount, AutocorrectFixtures.forms.count)
        TestSupport.expectEqual((0 ..< lexicon.formCount).map(lexicon.form(at:)), AutocorrectFixtures.forms)
        TestSupport.expectEqual((0 ..< lexicon.formCount).map(lexicon.frequency(ofFormAt:)), AutocorrectFixtures.freqs)
        for (id, form) in AutocorrectFixtures.forms.enumerated() {
            TestSupport.expectEqual(lexicon.formID(of: form), id)
            TestSupport.expectEqual(lexicon.frequency(of: form), AutocorrectFixtures.freqs[id])
        }
        TestSupport.expectEqual(lexicon.keyCount, AutocorrectFixtures.keyForms.count)
        for entry in AutocorrectFixtures.keyForms { TestSupport.expectEqual(lexicon.forms(ofKey: entry.key), entry.forms) }
        for missing in ["", "zork", "the'", "Cat", "ca", "cats", "can''t", "<unk>", "aa"] {
            TestSupport.expect(!lexicon.contains(missing), "not a form: \(missing)")
            TestSupport.expect(lexicon.frequency(of: missing) == nil, "no frequency: \(missing)")
        }
        TestSupport.expectEqual(lexicon.forms(ofKey: "ca"), [])
        TestSupport.expectEqual(lexicon.forms(ofKey: "can't"), [])
        TestSupport.expectEqual(lexicon.longestKey, AutocorrectFixtures.keyForms.map(\.key.count).max())
        // The writer here builds the same file from the forms.
        TestSupport.expectEqual(AutocorrectTestFiles.lexicon(Array(zip(AutocorrectFixtures.forms, AutocorrectFixtures.freqs))),
                                AutocorrectFixtures.data(AutocorrectFixtures.lexiconBase64))
    }

    private static func testCandidatesMatchTheReference() {
        TestSupport.expect(!AutocorrectFixtures.candidates.isEmpty, "no candidate fixtures")
        let corrector = Autocorrector(lexicon: fixtureLexicon, model: fixtureModel("unigram"), touch: fixtureTouch)
        for fixture in AutocorrectFixtures.candidates {
            let p = params { $0.maxEdits = fixture.maxEdits; $0.maxEditsShort = fixture.maxEdits }
            TestSupport.expectEqual(corrector.candidates(key: fixture.key, params: p), fixture.keys)
        }
    }

    private static func expectClose(_ actual: [Double], _ expected: [Double], tolerance: Double, _ message: String) {
        TestSupport.expect(actual.count == expected.count, "\(message): count")
        for (index, (a, e)) in zip(actual, expected).enumerated() where !(abs(a - e) <= tolerance) {
            TestSupport.expect(false, "\(message) word \(index): \(a) vs \(e)")
        }
    }

    private static func testLogProbsMatchTheReference() {
        var models = Set<String>()
        // One model per kind for every context (caches in use) and a fresh one each (cold): both match.
        let shared = ["unigram", "ngram", "lstm"].reduce(into: [String: WordModel]()) { $0[$1] = fixtureModel($1) }
        for fixture in AutocorrectFixtures.logProbs {
            models.insert(fixture.model)
            let label = "\(fixture.model) \(fixture.context)"
            expectClose(fixtureModel(fixture.model).logProbs(context: fixture.context, words: fixture.words), fixture.logProbs,
                        tolerance: 1e-5, "cold \(label)")
            expectClose(shared[fixture.model]!.logProbs(context: fixture.context, words: fixture.words), fixture.logProbs,
                        tolerance: 1e-5, "shared \(label)")
        }
        TestSupport.expectEqual(models, ["unigram", "ngram", "lstm"])
    }

    private static func testModelsAreNormalized() {
        // Over the lexicon's forms, "<unk>" and "</s>" each model's probabilities sum to 1 (the unigram has
        // no "</s>": it scores as "<unk>"), and a word outside the vocabulary gets "<unk>"'s.
        let vocabulary = AutocorrectFixtures.forms + ["<unk>", "</s>"]
        for name in ["unigram", "ngram", "lstm"] {
            let model = fixtureModel(name)
            for context in [[], ["i"], ["you", "were"], ["zork", "can't"], ["the", "the", "the", "cat"], ["<s>", "</s>"]] {
                let logProbs = model.logProbs(context: context, words: vocabulary + ["zork", "<s>"])
                TestSupport.expect(logProbs.allSatisfy(\.isFinite), "\(name) finite")
                let words = name == "unigram" ? logProbs.prefix(vocabulary.count - 1) : logProbs.prefix(vocabulary.count)
                let total = words.map(exp).reduce(0, +)
                TestSupport.expect(abs(total - 1) <= 1e-5, "\(name) \(context) sums to \(total)")
                TestSupport.expectEqual(logProbs[vocabulary.count], logProbs[vocabulary.count - 2])
                TestSupport.expectEqual(logProbs[vocabulary.count + 1], logProbs[vocabulary.count - 2])
            }
            TestSupport.expect(model.inVocab("the") && model.inVocab("<unk>") && !model.inVocab("zork") && !model.inVocab("<s>"),
                               "\(name) vocabulary")
            TestSupport.expectEqual(model.inVocab("</s>"), name != "unigram")
        }
        // Only the last two words matter to the trigram.
        let ngram = fixtureModel("ngram")
        TestSupport.expectEqual(ngram.logProbs(context: ["zork", "you", "were"], words: vocabulary),
                                ngram.logProbs(context: ["you", "were"], words: vocabulary))
    }

    private static func testLSTMCacheMatchesACold() {
        // A sentence typed a word at a time (each context one step from the cached one), then contexts that
        // branch and return: every value is exactly a cold model's; the cache stays bounded.
        let model = fixtureModel("lstm") as! LSTMWordModel
        let words = AutocorrectFixtures.forms + ["<unk>", "</s>", "zork"]
        let sentence = ["they", "love", "their", "cat", "more", "than", "the", "dog", "and", "it", "is", "good"]
        var contexts = (0 ... sentence.count).map { Array(sentence.prefix($0)) }
        contexts += [["they", "love"], ["i"], [], ["zork"], ["they", "love", "their", "dog"]]
        for context in contexts {
            let cold = fixtureModel("lstm")
            TestSupport.expectEqual(model.logProbs(context: context, words: words), cold.logProbs(context: context, words: words))
        }
        for index in 0 ..< 100 { _ = model.logProbs(context: [AutocorrectFixtures.forms[index % 46], "i", "\(index)"], words: ["the"]) }
        TestSupport.expect(model.cachedCount <= LSTMWordModel.cacheLimit, "cache bounded: \(model.cachedCount)")
        let cold = fixtureModel("lstm")
        TestSupport.expectEqual(model.logProbs(context: sentence, words: words), cold.logProbs(context: sentence, words: words))
    }

    private static func testForgetContextDropsCachedContexts() {
        // The keyboard forgets contexts when it hides: the LSTM's cached states go, and corrections and log
        // probabilities are the same afterwards.
        let model = fixtureModel("lstm") as! LSTMWordModel
        let corrector = Autocorrector(lexicon: fixtureLexicon, model: model, touch: fixtureTouch)
        let words = AutocorrectFixtures.forms + ["<unk>", "</s>"]
        let context = "they love their "
        let points = centreTaps("cst")
        let before = corrector.correct(context: context, word: "cst", points: points, keys: fixtureKeys, params: .standard)
        let logProbs = model.logProbs(context: ["they", "love", "their"], words: words)
        TestSupport.expect(model.cachedCount > 0, "contexts cached")
        corrector.forgetContext()
        TestSupport.expectEqual(model.cachedCount, 0)
        TestSupport.expectEqual(corrector.correct(context: context, word: "cst", points: points, keys: fixtureKeys, params: .standard), before)
        TestSupport.expectEqual(model.logProbs(context: ["they", "love", "their"], words: words), logProbs)
        // Every model forgets on request: the corrector passes it on.
        let fake = FakeModel(["cat": 0.5])
        Autocorrector(lexicon: fixtureLexicon, model: fake, touch: fixtureTouch).forgetContext()
        TestSupport.expectEqual(fake.forgotten, 1)
        for name in ["unigram", "ngram"] {
            let other = fixtureModel(name)
            let expected = other.logProbs(context: ["they", "love", "their"], words: words)
            other.forgetContext()
            TestSupport.expectEqual(other.logProbs(context: ["they", "love", "their"], words: words), expected)
        }
    }

    private static func testCorrectionsMatchTheReference() {
        // Expected with the fixture's spelling tables, which every params without wSpelling ignores.
        var models: [String: Autocorrector] = [:]
        var counts: [String: Int] = [:]
        var changed = 0, spelled = 0, spelledChanged = 0
        let keys = fixtureKeys
        for (index, fixture) in AutocorrectFixtures.corrections.enumerated() {
            let corrector = models[fixture.model]
                ?? Autocorrector(lexicon: fixtureLexicon, model: fixtureModel(fixture.model), touch: fixtureTouch, spelling: fixtureSpelling)
            models[fixture.model] = corrector
            let points: [(x: Double, y: Double)?] = zip(fixture.xs, fixture.ys).map { x, y in x.flatMap { x in y.map { (x, $0) } } }
            let got = corrector.correct(context: fixture.context, word: fixture.typed, points: points, keys: keys,
                                        params: fixtureParams(fixture.params))
            TestSupport.expect(got == fixture.expected,
                               "correction \(index) \(fixture.model) \(AutocorrectFixtures.params[fixture.params].name) \"\(fixture.context)\" \(fixture.typed): \(got) vs \(fixture.expected)")
            counts[fixture.model, default: 0] += 1
            if fixture.expected != fixture.typed { changed += 1 }
            if AutocorrectFixtures.params[fixture.params].wSpelling > 0 {
                spelled += 1
                if fixture.expected != fixture.typed { spelledChanged += 1 }
            }
        }
        TestSupport.expect(counts.keys.sorted() == ["lstm", "ngram", "unigram"] && counts.values.allSatisfy { $0 >= 20 }, "per model \(counts)")
        TestSupport.expect(changed >= 20, "corrections that change the word: \(changed)")
        TestSupport.expect(spelled >= 30 && spelledChanged >= 20, "spelling corrections \(spelled), changing the word \(spelledChanged)")
    }

    // MARK: Files

    static func patched(_ data: Data, at offset: Int, _ bytes: [UInt8]) -> Data {
        var data = data
        data.replaceSubrange(offset ..< offset + bytes.count, with: bytes)
        return data
    }

    static func error(_ body: () throws -> Void) -> WordFileError? {
        do {
            try body()
            return nil
        } catch {
            return error as? WordFileError
        }
    }

    private static func testLexiconFileIsValidated() {
        let valid = AutocorrectFixtures.data(AutocorrectFixtures.lexiconBase64)
        func error(_ data: Data) -> WordFileError? { Self.error { _ = try WordLexicon(data: data) } }
        TestSupport.expectEqual(error(valid), nil)
        // A slice that starts off an 8-byte boundary reads the same.
        let slice = (Data([1, 2, 3]) + valid).dropFirst(3)
        TestSupport.expectEqual(try! WordLexicon(data: slice).forms(ofKey: "cant"), ["can't", "cant"])
        TestSupport.expectEqual(error(patched(valid, at: 0, Array("LFWX".utf8))), .badMagic)
        TestSupport.expectEqual(error(Data("LF".utf8)), .wrongSize)
        TestSupport.expectEqual(error(valid.prefix(40)), .wrongSize)
        TestSupport.expectEqual(error(patched(valid, at: 4, [2, 0, 0, 0])), .unsupportedVersion)
        TestSupport.expectEqual(error(valid.dropLast(8)), .wrongSize)
        TestSupport.expectEqual(error(valid + Data(count: 8)), .wrongSize)
        TestSupport.expectEqual(error(patched(valid, at: 16, [0, 0, 0, 0])), .unsupportedShape)  // edges ≠ M − 1
        TestSupport.expectEqual(error(patched(valid, at: 28, [1, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(valid, at: 40, Array(repeating: 0, count: 8))), .invalidValues)  // unk mass 0
        TestSupport.expectEqual(error(patched(valid, at: 48, [valid[48] ^ 1])), .lexiconMismatch)
        // The longest key, a form's text, an edge's letter and a form's place in the trie.
        TestSupport.expectEqual(error(patched(valid, at: 24, [9, 0, 0, 0])), .invalidStructure)
        let text = valid.range(of: Data("andcan".utf8))!.lowerBound
        TestSupport.expectEqual(error(patched(valid, at: text, Array("anD".utf8))), .invalidStructure)
        TestSupport.expectEqual(error(patched(valid, at: text, Array("cnd".utf8))), .invalidStructure)
        let n = AutocorrectFixtures.forms.count, t = AutocorrectFixtures.forms.map(\.utf8.count).reduce(0, +)
        func padded(_ bytes: Int) -> Int { (bytes + 7) / 8 * 8 }
        let nodeEdges = 80 + padded(4 * (n + 1)) + padded(n) + padded(t)
        let m = valid.withUnsafeBytes { Int(UInt32(littleEndian: $0.loadUnaligned(fromByteOffset: 12, as: UInt32.self))) }
        let letters = nodeEdges + padded(4 * (m + 1))
        TestSupport.expectEqual(error(patched(valid, at: letters, [UInt8(ascii: "z")])), .invalidStructure)
        let formList = letters + padded(m - 1) + padded(4 * (m - 1)) + padded(4 * (m + 1))
        TestSupport.expectEqual(error(patched(valid, at: formList, [1, 0, 0, 0])), .invalidStructure)
    }

    private static func testLexiconWithDescendingOffsetsThrows() {
        // node_edges and node_forms that start and end right but decrease in between: a bad file throws, it
        // never traps. Lexicon "ab", "ac": nodes "", "a", "ab", "ac"; node_edges [0, 1, 3, 3, 3], node_forms
        // [0, 0, 0, 1, 2].
        let valid = AutocorrectTestFiles.lexicon([("ab", 10), ("ac", 20)])
        func error(_ data: Data) -> WordFileError? { Self.error { _ = try WordLexicon(data: data) } }
        TestSupport.expectEqual(error(valid), nil)
        let text = 80 + 16 + 8 + 8  // form_offsets (3 u32), form_freqs (2), text (4), each padded to 8
        let nodeEdges = text, nodeForms = nodeEdges + 24 + 8 + 16  // node_edges (5 u32), letters (3), children (3 u32)
        func u32s(_ values: [UInt32]) -> [UInt8] { values.flatMap { withUnsafeBytes(of: $0.littleEndian) { Array($0) } } }
        TestSupport.expectEqual(Array(valid[nodeEdges ..< nodeEdges + 20]), u32s([0, 1, 3, 3, 3]))
        TestSupport.expectEqual(Array(valid[nodeForms ..< nodeForms + 20]), u32s([0, 0, 0, 1, 2]))
        TestSupport.expectEqual(error(patched(valid, at: nodeEdges, u32s([0, 3, 1, 3, 3]))), .invalidStructure)
        TestSupport.expectEqual(error(patched(valid, at: nodeForms, u32s([0, 0, 2, 1, 2]))), .invalidStructure)
        TestSupport.expectEqual(error(patched(valid, at: nodeForms, u32s([0, 0, 0, 3, 2]))), .invalidStructure)
        // A form offset past the text, and offsets decreasing.
        TestSupport.expectEqual(error(patched(valid, at: 80, u32s([0, 9, 4]))), .invalidStructure)
        TestSupport.expectEqual(error(patched(valid, at: 80, u32s([0, 3, 4]) + u32s([2]))), .invalidStructure)
    }

    private static func testModelHeadersWithHugeSizesThrow() {
        // Header sizes whose products overflow throw rather than trap.
        let ngram = AutocorrectFixtures.data(AutocorrectFixtures.ngramBase64)
        let lstm = AutocorrectFixtures.data(AutocorrectFixtures.lstmBase64)
        let huge: [UInt8] = [0xFF, 0xFF, 0xFF, 0xFF]
        TestSupport.expectEqual(error { _ = try NGramWordModel(data: patched(patched(ngram, at: 8, huge), at: 12, huge), lexicon: fixtureLexicon) },
                                .unsupportedShape)
        TestSupport.expectEqual(error { _ = try NGramWordModel(data: patched(ngram, at: 8, huge), lexicon: fixtureLexicon) }, .unsupportedShape)
        TestSupport.expectEqual(error { _ = try NGramWordModel(data: patched(ngram, at: 12, huge), lexicon: fixtureLexicon) }, .unsupportedShape)
        TestSupport.expectEqual(error { _ = try NGramWordModel(data: patched(ngram, at: 72, huge + huge), lexicon: fixtureLexicon) },
                                .unsupportedShape)
        TestSupport.expectEqual(error { _ = try LSTMWordModel(data: patched(lstm, at: 8, huge), lexicon: fixtureLexicon) }, .unsupportedShape)
        TestSupport.expectEqual(error { _ = try LSTMWordModel(data: patched(lstm, at: 12, huge), lexicon: fixtureLexicon) }, .unsupportedShape)
        let lexicon = AutocorrectFixtures.data(AutocorrectFixtures.lexiconBase64)
        for offset in [8, 12, 20] {
            TestSupport.expect(error { _ = try WordLexicon(data: patched(lexicon, at: offset, huge)) } != nil, "lexicon header \(offset)")
        }
    }

    private static func testNGramFileIsValidated() {
        let valid = AutocorrectFixtures.data(AutocorrectFixtures.ngramBase64)
        let lexicon = fixtureLexicon
        func error(_ data: Data, _ lexicon: WordLexicon = fixtureLexicon) -> WordFileError? {
            Self.error { _ = try NGramWordModel(data: data, lexicon: lexicon) }
        }
        TestSupport.expectEqual(error(valid), nil)
        TestSupport.expectEqual((try! NGramWordModel(data: valid, lexicon: lexicon)).order, 3)
        TestSupport.expectEqual(error(patched(valid, at: 0, Array("LFWL".utf8))), .badMagic)
        TestSupport.expectEqual(error(patched(valid, at: 4, [2, 0, 0, 0])), .unsupportedVersion)
        TestSupport.expectEqual(error(valid.prefix(60)), .wrongSize)
        TestSupport.expectEqual(error(valid.dropLast(8)), .wrongSize)
        TestSupport.expectEqual(error(valid + Data(count: 8)), .wrongSize)
        TestSupport.expectEqual(error(patched(valid, at: 8, [0, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(valid, at: 12, [40, 0, 0, 0])), .unsupportedShape)
        // Another lexicon: its hash, or the form count.
        TestSupport.expectEqual(error(patched(valid, at: 40, [valid[40] ^ 1])), .lexiconMismatch)
        let other = Self.lexicon(Array(zip(AutocorrectFixtures.forms, AutocorrectFixtures.freqs)) + [("zork", 1)])
        TestSupport.expectEqual(error(valid, other), .lexiconMismatch)
        TestSupport.expectEqual(error(patched(valid, at: 16, [51, 0, 0, 0])), .lexiconMismatch)
        // A built model: unsorted codes, an n-gram without its context, a non-finite value.
        let forms = AutocorrectFixtures.forms
        let p1 = [Float](repeating: 1 / Float(forms.count + 2), count: forms.count + 4)
        func model(contexts: [(UInt64, Float, Float)], grams: [(UInt64, Float)], p1: [Float] = p1) -> Data {
            AutocorrectTestFiles.ngram(forms: forms, order: 2, bits: 6, p1: p1, tables: [(0.5, contexts, grams)])
        }
        TestSupport.expectEqual(error(model(contexts: [(4, 3, 0.5)], grams: [(4 << 6 | 5, 2), (4 << 6 | 6, 1)])), nil)
        TestSupport.expectEqual(error(model(contexts: [(4, 3, 0.5)], grams: [(4 << 6 | 6, 2), (4 << 6 | 5, 1)])), .invalidStructure)
        TestSupport.expectEqual(error(model(contexts: [(5, 3, 0.5), (4, 3, 0.5)], grams: [])), .invalidStructure)
        TestSupport.expectEqual(error(model(contexts: [(4, 3, 0.5)], grams: [(7 << 6 | 5, 2)])), .invalidStructure)
        TestSupport.expectEqual(error(model(contexts: [(4, 0, 0.5)], grams: [])), .invalidValues)
        TestSupport.expectEqual(error(model(contexts: [], grams: [], p1: [.nan] + p1.dropFirst())), .invalidValues)
    }

    private static func testLSTMFileIsValidated() {
        let valid = AutocorrectFixtures.data(AutocorrectFixtures.lstmBase64)
        func error(_ data: Data, _ lexicon: WordLexicon = fixtureLexicon) -> WordFileError? {
            Self.error { _ = try LSTMWordModel(data: data, lexicon: lexicon) }
        }
        TestSupport.expectEqual(error(valid), nil)
        let model = try! LSTMWordModel(data: valid, lexicon: fixtureLexicon)
        TestSupport.expectEqual([model.embed, model.hidden, model.vocabulary], [4, 6, 20])
        TestSupport.expectEqual(error(patched(valid, at: 0, Array("LFWN".utf8))), .badMagic)
        TestSupport.expectEqual(error(patched(valid, at: 4, [0, 0, 0, 0])), .unsupportedVersion)
        TestSupport.expectEqual(error(valid.prefix(79)), .wrongSize)
        TestSupport.expectEqual(error(valid.dropLast(8)), .wrongSize)
        TestSupport.expectEqual(error(valid + Data(count: 8)), .wrongSize)
        TestSupport.expectEqual(error(patched(valid, at: 8, [0, 0, 0, 0])), .unsupportedShape)
        TestSupport.expectEqual(error(patched(valid, at: 16, [47, 0, 0, 0])), .unsupportedShape)  // V > N
        TestSupport.expectEqual(error(patched(valid, at: 48, [valid[48] ^ 1])), .lexiconMismatch)
        let other = Self.lexicon(Array(zip(AutocorrectFixtures.forms, AutocorrectFixtures.freqs)) + [("zork", 1)])
        TestSupport.expectEqual(error(valid, other), .lexiconMismatch)
        TestSupport.expectEqual(error(patched(valid, at: 24, (1.0).bitPattern.littleEndianBytes)), .invalidValues)  // u 1 with rare forms
        // form_words disagreeing with words, and a non-finite weight.
        let formWords = 80 + (4 * 20 + 7) / 8 * 8
        TestSupport.expectEqual(error(patched(valid, at: formWords, [0xFF, 0xFF, 0xFF, 0x7F])), .invalidStructure)
        let embedding = formWords + (4 * 46 + 7) / 8 * 8
        TestSupport.expectEqual(error(patched(valid, at: embedding, [0, 0, 0xC0, 0x7F])), .invalidValues)
        // Every form a model word: u must be 1.
        let forms = AutocorrectFixtures.forms
        let all = AutocorrectTestFiles.lstm(forms: forms, freqs: AutocorrectFixtures.freqs, words: Array(forms.indices), embed: 3, hidden: 2,
                                            u: 1, seed: 7)
        TestSupport.expectEqual(error(all), nil)
        TestSupport.expectEqual(error(patched(all, at: 24, (0.5).bitPattern.littleEndianBytes)), .invalidValues)
    }

    private static func testSpellingFileIsValidated() {
        let valid = AutocorrectFixtures.data(AutocorrectFixtures.spellingBase64)
        func error(_ data: Data) -> WordFileError? { Self.error { _ = try SpellingTables(data: data) } }
        TestSupport.expectEqual(error(valid), nil)
        TestSupport.expectEqual(valid.count, 11_032)
        TestSupport.expectEqual(SpellingTables.fileSize, 11_032)
        // Widened float32: the writer here gives the same bytes back; −∞ diagonals and a slice off an 8-byte
        // boundary read the same.
        let tables = fixtureSpelling
        TestSupport.expectEqual(AutocorrectTestFiles.spelling(tables), valid)
        TestSupport.expectEqual([tables.sub.count, tables.dele.count, tables.ins.count, tables.trans.count], [676, 702, 702, 676])
        TestSupport.expect((0 ..< 26).allSatisfy { tables.sub[$0 * 27] == -.infinity && tables.trans[$0 * 27] == -.infinity }, "diagonals")
        TestSupport.expectEqual(tables.trans[4 * 26 + 8], Double(Float(log(0.5))))  // trans[e, i]
        TestSupport.expectEqual(tables.ins[SpellingTables.start * 26 + 4], Double(Float(log(0.3))))  // ins[START, e]
        TestSupport.expectEqual(try! SpellingTables(data: (Data([1, 2, 3]) + valid).dropFirst(3)), tables)
        TestSupport.expectEqual(error(patched(valid, at: 0, Array("LFWL".utf8))), .badMagic)
        TestSupport.expectEqual(error(patched(valid, at: 4, [2, 0, 0, 0])), .unsupportedVersion)
        TestSupport.expectEqual(error(Data("LFW".utf8)), .wrongSize)
        TestSupport.expectEqual(error(valid.prefix(6)), .wrongSize)
        TestSupport.expectEqual(error(valid.prefix(8)), .wrongSize)
        TestSupport.expectEqual(error(valid.dropLast(4)), .wrongSize)
        TestSupport.expectEqual(error(valid.dropLast(8)), .wrongSize)
        TestSupport.expectEqual(error(valid + Data(count: 8)), .wrongSize)
        // Values outside the tables' rules: NaN, a positive or infinite entry, −∞ off a diagonal, a finite diagonal.
        func f32(_ value: Float) -> [UInt8] { withUnsafeBytes(of: value.bitPattern.littleEndian) { Array($0) } }
        let sub = 8, dele = 8 + 4 * 676
        for (offset, value) in [(sub + 4, Float.nan), (sub + 4 * 3, 0.5), (sub + 4 * 2, Float.infinity), (dele + 4 * 5, -Float.infinity),
                                (sub + 4 * 27, -1)] {
            TestSupport.expect(error(patched(valid, at: offset, f32(value))) == .invalidValues, "\(offset) \(value)")
        }
        TestSupport.expectEqual(error(patched(valid, at: dele, f32(0))), nil)  // log 1 is a probability
        TestSupport.expectEqual(error(patched(valid, at: dele, f32(-0.0))), nil)
        // Tables of the wrong size, from values.
        TestSupport.expectEqual(Self.error { _ = try SpellingTables(sub: tables.sub, dele: tables.sub, ins: tables.ins, trans: tables.trans) },
                                .unsupportedShape)
    }

    // MARK: Benchmark

    private static func testBenchmark() {
        // Timing on the Mac, printed, not asserted: a lexicon of 60k invented keys (4-12 letters), a 12-letter
        // word with about 150 candidates within two edits, and each model kind (an n-gram and an LSTM of a
        // device-like size, with random contents).
        var random = SplitMix64(seed: 11)
        let alphabet = Array("etaoinshrdlucmfwypvbgkjqxz")
        var entries: [String: Int] = [:]
        let base = "interstellar"
        while entries.count < 60_000 {
            if Double.random(in: 0 ..< 1, using: &random) < 0.004 {
                var letters = Array(base)
                for _ in 0 ..< Int.random(in: 1 ... 2, using: &random) {
                    let at = Int.random(in: 0 ..< letters.count, using: &random)
                    switch Int.random(in: 0 ..< 3, using: &random) {
                    case 0: letters[at] = alphabet.randomElement(using: &random)!
                    case 1: letters.remove(at: at)
                    default: letters.insert(alphabet.randomElement(using: &random)!, at: at)
                    }
                }
                entries[String(letters)] = Int.random(in: 0 ... 255, using: &random)
            } else {
                let word = String((0 ..< Int.random(in: 4 ... 12, using: &random)).map { _ in
                    alphabet[min(Int(-log(Double.random(in: 1e-9 ..< 1, using: &random)) * 5), 25)]
                })
                entries[word] = Int.random(in: 0 ... 255, using: &random)
            }
        }
        let start = Date()
        let data = AutocorrectTestFiles.lexicon(entries.map { ($0.key, $0.value) })
        let built = Date()
        let lexicon = try! WordLexicon(data: data)
        let loaded = Date()
        let forms = AutocorrectTestFiles.sortedForms(entries)
        let freqs = forms.map { entries[$0]! }
        let lstm = try! LSTMWordModel(data: AutocorrectTestFiles.lstm(forms: forms, freqs: freqs, words: Array(0 ..< 16_000), embed: 64,
                                                                      hidden: 128, u: 0.3, seed: 5), lexicon: lexicon)
        // An order-3 n-gram whose contexts each word of the sentence has: three binary searches per word.
        let bits = 16, sentence: [UInt64] = ["we", "went", "to", "the"].map { UInt64(lexicon.formID(of: $0).map { $0 + 4 } ?? 3) }
        let p1 = [Float](repeating: 1 / Float(forms.count + 2), count: forms.count + 4)
        let bigram = (sentence[3], Float(100), Float(0.5)), trigram = (sentence[2] << 16 | sentence[3], Float(50), Float(0.5))
        let grams = Array(Set((0 ..< 3_000).map { _ in UInt64.random(in: 4 ..< UInt64(forms.count + 4), using: &random) })).sorted()
        let ngram = try! NGramWordModel(data: AutocorrectTestFiles.ngram(forms: forms, order: 3, bits: bits, p1: p1, tables: [
            (0.5, [bigram], grams.map { (bigram.0 << 16 | $0, 1) }), (0.5, [trigram], grams.map { (trigram.0 << 16 | $0, 1) }),
        ]), lexicon: lexicon)
        let models: [(String, WordModel)] = [("unigram", UnigramWordModel(lexicon: lexicon)), ("ngram", ngram), ("lstm", lstm)]
        let word = "intrestellar"
        let points = word.map { sample($0, sigma: 0.3, &random) }
        var p = AutocorrectParams.standard
        p.marginOOV = 1
        let candidates = Autocorrector(lexicon: lexicon, model: models[0].1, touch: touch).candidates(key: word, params: p).count
        print("  autocorrect benchmark: lexicon of \(lexicon.formCount) forms built in \(ms(built.timeIntervalSince(start))), "
            + "loaded and validated in \(ms(loaded.timeIntervalSince(built))); \(candidates) candidates for \"\(word)\"")
        for (name, model) in models {
            let corrector = Autocorrector(lexicon: lexicon, model: model, touch: touch)
            _ = corrector.correct(context: "we went to the ", word: word, points: points, keys: keys, params: p)
            let runs = 10
            let begin = Date()
            var result = ""
            for run in 0 ..< runs {
                // A context not seen before each run, one word longer than a cached one: one LSTM step.
                result = corrector.correct(context: "we went to the \(forms[run * 7]) ", word: word, points: points, keys: keys, params: p)
            }
            print("  autocorrect benchmark: \(name) correct() \(ms(Date().timeIntervalSince(begin) / Double(runs))) per word -> \(result)")
        }
        // The channel alone (unigram), motor-only and with the spelling channel: its per-word terms and loops.
        let spelled = Autocorrector(lexicon: lexicon, model: models[0].1, touch: touch, spelling: AutocorrectTestFiles.randomSpelling(&random))
        for weight in [0.0, 0.1] {
            var q = p
            q.wSpelling = weight
            _ = spelled.correct(context: "we went to the ", word: word, points: points, keys: keys, params: q)
            let runs = 20
            let begin = Date()
            var result = ""
            for _ in 0 ..< runs { result = spelled.correct(context: "we went to the ", word: word, points: points, keys: keys, params: q) }
            print("  autocorrect benchmark: unigram wSpelling \(weight) correct() \(ms(Date().timeIntervalSince(begin) / Double(runs))) per word -> \(result)")
        }
    }

    private static func ms(_ seconds: TimeInterval) -> String { String(format: "%.2f ms", seconds * 1000) }
}

private extension UInt64 {
    var littleEndianBytes: [UInt8] { withUnsafeBytes(of: littleEndian) { Array($0) } }
}
